function normalizeSearch(s){return String(s||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase().replace(/đ/g,'d').trim()}
function showLearningTab(tab){
 const map={dictionary:['dictionarySection','tabDictionary'],phrases:['phrasesSection','tabPhrases'],grammar:['grammarSection','tabGrammar'],emails:['emailsSection','tabEmails'],calls:['callsSection','tabCalls']};
 Object.entries(map).forEach(([key,ids])=>{document.getElementById(ids[0]).hidden=key!==tab;document.getElementById(ids[1]).classList.toggle('primary',key===tab)});
 if(tab==='dictionary') document.getElementById('dictionaryQuery').focus({preventScroll:true});
}
function renderDictionary(){
 const q=document.getElementById('dictionaryQuery').value.trim(); const target=document.getElementById('dictionaryResults');
 if(!q){document.getElementById('dictionaryCount').textContent=`Có ${DATA.length} mục trong Library. Nhập từ để bắt đầu tra cứu.`;target.innerHTML='';return;}
 const nq=normalizeSearch(q);
 const matches=DATA.map((x,i)=>({x,i,hay:[x.jp,x.reading,x.en,x.vn,x.hv,x.source].map(normalizeSearch)}))
  .map(o=>({...o,score:o.hay.reduce((n,h,idx)=>n+(h===nq?10:0)+(h.startsWith(nq)?4:0)+(h.includes(nq)?1:0),0)}))
  .filter(o=>o.score>0).sort((a,b)=>b.score-a.score||a.x.jp.length-b.x.jp.length).slice(0,60);
 document.getElementById('dictionaryCount').textContent=matches.length?`Tìm thấy ${matches.length}${matches.length===60?' mục đầu tiên':''}.`: 'Không tìm thấy mục phù hợp. Thử từ khóa ngắn hơn hoặc ngôn ngữ khác.';
 target.innerHTML=matches.map(({x})=>`<article class="dict-item"><div class="dict-top"><div><div class="dict-jp">${escapeHTML(x.jp)}</div><div class="dict-reading">${escapeHTML(x.reading||'')}</div></div><div class="small">${escapeHTML(x.cat||'')}</div></div><div class="dict-meta"><div><span class="dict-label">English</span><br>${escapeHTML(x.en||'—')}</div><div><span class="dict-label">Tiếng Việt</span><br>${escapeHTML(x.vn||'—')}</div><div><span class="dict-label">Âm Hán-Việt từng chữ</span><br>${escapeHTML(x.hv||'—')}</div></div></article>`).join('');
}
const CATEGORY_LABELS={greetings:'Chào hỏi & làm quen',daily:'Thói quen hằng ngày',hobbies:'Sở thích cá nhân',work:'Công việc & kinh nghiệm'};
function renderPhrases(){
 const c=document.getElementById('phraseCategory').value; const list=PHRASES.filter(x=>c==='all'||x.c===c);
 document.getElementById('phraseResults').innerHTML=list.map(x=>`<article class="phrase-item"><div class="phrase-head">${escapeHTML(CATEGORY_LABELS[x.c])}</div><div class="phrase-en">${escapeHTML(x.en)}</div><div class="phrase-jp">🇯🇵 ${escapeHTML(x.jp)}</div><div class="phrase-vn">🇻🇳 ${escapeHTML(x.vn)}</div><div class="email-actions"><button onclick="copyPhraseByIndex(${PHRASES.indexOf(x)})">Sao chép câu tiếng Anh</button></div></article>`).join('');
}
function renderGrammar(){
 const c=document.getElementById('grammarCategory').value; const list=GRAMMAR.filter(x=>c==='all'||x.c===c);
 document.getElementById('grammarResults').innerHTML=list.map((x,i)=>`<article class="phrase-item"><div class="phrase-head">${escapeHTML(({prepositions:'Giới từ',time:'Thời gian & lịch trình',expressions:'Cụm từ giao tiếp',agreement:'Đồng ý & xác nhận',connectors:'Liên kết ý',email:'Email & điện thoại'})[x.c]||x.c)}</div><div class="phrase-en"><b>${escapeHTML(x.term)}</b></div><div class="phrase-vn">${escapeHTML(x.meaning)}</div><p><b>Cấu trúc / cách dùng:</b> ${escapeHTML(x.rule)}</p>${x.examples.map(e=>`<div style="padding:6px 0;border-top:1px solid #e5e7eb"><div class="phrase-en">${escapeHTML(e[0])}</div><div class="phrase-vn">${escapeHTML(e[1])}</div></div>`).join('')}<p class="small"><b>Lưu ý:</b> ${escapeHTML(x.note||'')}</p></article>`).join('');
}
function renderDialogues(){
 const c=document.getElementById('dialogueCategory').value; const list=DIALOGUES.filter(x=>c==='all'||x.c===c);
 document.getElementById('dialogueResults').innerHTML=list.map((d,di)=>`<article class="phrase-item"><div class="phrase-head">${escapeHTML(d.title)}</div>${d.turns.map((t,i)=>`<div class="dialogue-turn" style="padding:8px 0;border-top:1px solid #e5e7eb"><div class="small"><b>${escapeHTML(t[0])}</b></div><div class="phrase-en">🇬🇧 ${escapeHTML(t[1])}</div><div class="phrase-jp">🇯🇵 ${escapeHTML(t[2])}</div><button onclick="copyDialogue(${DIALOGUES.indexOf(d)},${i},1)">Copy English</button> <button onclick="copyDialogue(${DIALOGUES.indexOf(d)},${i},2)">日本語をコピー</button></div>`).join('')}<button onclick="copyDialogueAll(${DIALOGUES.indexOf(d)},1)">Copy whole dialogue (English)</button> <button onclick="copyDialogueAll(${DIALOGUES.indexOf(d)},2)">会話全体をコピー（日本語）</button></article>`).join('');
}
function copyDialogue(di,ti,lang){const t=DIALOGUES[di]?.turns[ti];if(t)copyText(t[lang]);}
function copyDialogueAll(di,lang){const d=DIALOGUES[di];if(d)copyText(d.turns.map(t=>t[0]+': '+t[lang]).join('\n'));}
function renderEmail(){
 const id=document.getElementById('emailTemplateSelect').value; const x=EMAILS.find(e=>e.id===id)||EMAILS[0];
 document.getElementById('emailTemplateContent').innerHTML=[['English',x.en],['日本語',x.jp],['Tiếng Việt',x.vn]].map(([lang,body])=>`<div class="email-block"><div class="email-lang">${lang}</div><div class="email-text">${escapeHTML(body)}</div><div class="email-actions"><button onclick="copyEmailByLang('${x.id}','${lang}')">Sao chép ${lang}</button></div></div>`).join('');
}
function copyPhraseByIndex(i){const x=PHRASES[i];if(x)copyText(x.en)}
function copyEmailByLang(id,lang){const x=EMAILS.find(e=>e.id===id);if(x)copyText(lang==='English'?x.en:lang==='日本語'?x.jp:x.vn)}
async function copyText(text){
 try{if(navigator.clipboard&&navigator.clipboard.writeText){await navigator.clipboard.writeText(text);alert('Đã sao chép.');return;}}catch(e){}
 const ta=document.createElement('textarea');ta.value=text;ta.style.position='fixed';ta.style.opacity='0';document.body.appendChild(ta);ta.select();let ok=false;try{ok=document.execCommand('copy')}catch(e){}ta.remove();alert(ok?'Đã sao chép.':'Không thể tự sao chép trên trình duyệt này. Bạn có thể chọn và sao chép nội dung thủ công.');
}
document.getElementById('dictionaryQuery').addEventListener('input',renderDictionary);
document.getElementById('phraseCategory').addEventListener('change',renderPhrases);
document.getElementById('dialogueCategory').addEventListener('change',renderDialogues);
document.getElementById('grammarCategory').addEventListener('change',renderGrammar);
document.getElementById('emailTemplateSelect').innerHTML=EMAILS.map(x=>`<option value="${x.id}">${escapeHTML(x.title)}</option>`).join('');
document.getElementById('emailTemplateSelect').addEventListener('change',renderEmail);
renderDictionary();renderPhrases();renderGrammar();renderDialogues();renderEmail();
